    use super::*;
    use crate::types::SymbolKind;

    fn block(code: &str, symbol_signature: Option<&str>) -> CodeBlock {
        CodeBlock {
            file: Utf8PathBuf::from("src/a.ts"),
            line_start: 1,
            line_end: 3,
